'use strict';
/*
 * Hundeschule · Pair Programming – Online-Tool für IF EF (Do 12.11. und UB Fr 13.11.)
 *
 * Start lokal:  npm install  &&  npm start   ->  http://localhost:3000
 * Lernende:     /            Paar eintragen, Rolle sehen, Gruppe bilden (Do);
 *                            Hindernis wählen, gestufte Hilfen, Quelltext hochladen,
 *                            gemeinsames Szenario (.gfar) herunterladen (Fr)
 * Lehrkraft:    /lehrkraft   Überblick, Freigaben, Arbeitsphase beenden, Rollentausch, Sicherung
 *
 * Umgebungsvariable (bei Render unter "Environment" setzen):
 *   LEHRER_PASSWORT   Passwort für die Lehrerseite (dringend empfohlen)
 *
 * Datenschutz: Gespeichert werden nur Vornamen bzw. Kürzel, Rollen, Gruppen und der abgegebene
 * Quelltext – nur im Arbeitsspeicher. Nach einem Neustart des Servers ist alles weg; die geöffnete
 * Lehrerseite stellt den Stand aus ihrer lokalen Sicherung wieder her. Nach 10 Tagen ohne Änderung
 * löscht der Server alles; die Lehrerseite hat außerdem einen Knopf „Alles löschen“.
 *
 * Das Startszenario (Hund, Hundeplatz, Bilder) ist am Ende dieser Datei eingebettet (BASIS).
 */

const path = require('path');
const crypto = require('crypto');
const http = require('http');
const express = require('express');
const { Server } = require('socket.io');

const PORT = process.env.PORT || 3000;
const PASSWORT = String(process.env.LEHRER_PASSWORT || '').trim();
const LEBENSDAUER_MS = 10 * 24 * 60 * 60 * 1000;
const MAX_PAARE_PRO_GRUPPE = 3;
const MAX_CODE = 20000;

/* Hindernisse (Klassen), die die Paare programmieren. Bild = Datei im Ordner images des Szenarios.
   info = kurze Angabe zum Umfang, damit die Paare ihre Wahl einschätzen können. */
const KLASSEN = [
  { name: 'Huerde', anzeige: 'Hürde', bild: 'huerde.png', info: '2 Attribute · 4 Methoden' },
  { name: 'Tunnel', anzeige: 'Tunnel', bild: 'tunnel.png', info: '3 Attribute · 3 Methoden' },
  { name: 'Slalom', anzeige: 'Slalom', bild: 'slalom.png', info: '3 Attribute · 3 Methoden, eine mit Parameter' },
];
const HILFE_THEMEN = ['attribute', 'konstruktor', 'methoden', 'p_fragt', 'p_null', 'p_eingabe'];
const KLASSE = Object.fromEntries(KLASSEN.map(k => [k.name, k]));

const app = express();
const server = http.createServer(app);
const io = new Server(server, { maxHttpBufferSize: 2e6 });
const INSTANZ = crypto.randomBytes(6).toString('hex');

/* ------------------------------------------------------------------ */
/* Zustand                                                             */
/* ------------------------------------------------------------------ */

function leererZustand() {
  return {
    freigabe: { gruppen: true, wahl: false, abgabe: false, download: false },
    abgabeBis: '',
    tausch: 0,                // wie oft die Rollen getauscht wurden
    paare: {},                // id -> { id, namen[], rollen[], gruppe, klasse, code, codeZeit, hilfen{}, seit }
    gruppen: {},              // id -> { id, name, seit }
    updatedAt: Date.now(),
  };
}
let Z = leererZustand();
const tokens = new Set();

const neueId = () => crypto.randomBytes(6).toString('hex');
const ID_RE = /^[a-f0-9]{12}$/;
const text = (v, max) => String(v == null ? '' : v).replace(/[\u0000-\u001f<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
const mischen = a => {
  for (let i = a.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const ROLLEN = ['Driver', 'Navigator', 'Tester'];

function paareDerGruppe(gid) {
  return Object.values(Z.paare).filter(p => p.gruppe === gid).sort((a, b) => a.seit - b.seit);
}
function istLeer() {
  return !Object.keys(Z.paare).length && !Object.keys(Z.gruppen).length;
}
function gruppeFertig(gid) {
  const ps = paareDerGruppe(gid);
  return ps.length > 0 && ps.every(p => p.code);
}

/* Ansicht für Lernende: ohne Quelltexte */
function oeffentlich() {
  return {
    freigabe: Z.freigabe,
    abgabeBis: Z.abgabeBis,
    tausch: Z.tausch,
    klassen: KLASSEN,
    paare: Object.values(Z.paare).sort((a, b) => a.seit - b.seit).map(p => ({
      id: p.id, namen: p.namen, rollen: p.rollen, gruppe: p.gruppe, klasse: p.klasse,
      abgegeben: !!p.code, codeZeit: p.codeZeit || null, hilfen: p.hilfen || {},
    })),
    gruppen: Object.values(Z.gruppen).sort((a, b) => a.seit - b.seit).map(g => ({ id: g.id, name: g.name, fertig: gruppeFertig(g.id) })),
  };
}
function voll() {
  const v = oeffentlich();
  v.instanz = INSTANZ;
  v.paare.forEach(p => { p.code = Z.paare[p.id].code || ''; p.seit = Z.paare[p.id].seit; });
  v.gruppen.forEach(g => { g.seit = Z.gruppen[g.id].seit; });
  return v;
}
function verteilen() {
  Z.updatedAt = Date.now();
  io.to('s').emit('s:zustand', oeffentlich());
  io.to('lk').emit('lk:zustand', voll());
}

/* ------------------------------------------------------------------ */
/* Prüfungen                                                           */
/* ------------------------------------------------------------------ */

function namenPruefen(liste) {
  const namen = (Array.isArray(liste) ? liste : []).map(n => text(n, 30)).filter(Boolean);
  if (namen.length < 2) return { fehler: 'Tragt mindestens zwei Namen ein.' };
  if (namen.length > 3) return { fehler: 'Höchstens drei Namen.' };
  return { namen };
}

function codePruefen(quelltext, klasse) {
  const q = String(quelltext || '').replace(/\r\n?/g, '\n');
  // Nur ein leeres oder viel zu langes Feld wird abgelehnt. Alles andere wird angenommen,
  // auch unfertige oder nicht übersetzbare Klassen: Die Gruppe überarbeitet sie gemeinsam.
  if (!q.trim()) return { fehler: 'Das Feld ist leer. Kopiert euren Quelltext mit Strg + A und Strg + C aus dem Greenfoot-Editor.' };
  if (q.length > MAX_CODE) return { fehler: 'Der Text ist zu lang. Habt ihr nur den Quelltext eurer Klasse kopiert?' };
  const code = /import\s+greenfoot/.test(q) ? q : 'import greenfoot.*;\n\n' + q;
  const hinweise = [];
  const m = q.match(/public\s+class\s+([^\s{]+)\s+extends\s+(\w+)/);
  if (!m) {
    hinweise.push('Ich finde keine Zeile wie „public class ' + klasse + ' extends Actor“. Habt ihr den ganzen Quelltext kopiert (Strg + A)?');
  } else {
    if (m[2] !== 'Actor') hinweise.push(`Eure Klasse erbt von ${m[2]}, sie soll aber von Actor erben („extends Actor“).`);
    if (m[1] !== klasse) {
      const umlaut = /[äöüÄÖÜß]/.test(m[1]) ? ' Bezeichner schreiben wir ohne Umlaute.' : '';
      hinweise.push(`Eure Klasse heißt „${m[1]}“, sie soll aber „${klasse}“ heißen.${umlaut}`);
    }
  }
  const auf = (q.match(/{/g) || []).length, zu = (q.match(/}/g) || []).length;
  if (auf !== zu) hinweise.push(`Es gibt ${auf} öffnende und ${zu} schließende geschweifte Klammern.`);
  if (new RegExp('void\\s+' + klasse + '\\s*\\(').test(q)) {
    hinweise.push(`Vor „${klasse}(…)“ steht void. Dann ist es eine Methode und kein Konstruktor: Greenfoot fragt beim Erzeugen nichts ab. Beim Konstruktor steht vor dem Namen kein void.`);
  } else if (!new RegExp('public\\s+' + klasse + '\\s*\\(').test(q)) {
    hinweise.push(`Ich finde keinen Konstruktor „public ${klasse}(…)“.`);
  }
  const hinweis = hinweise.length
    ? hinweise.join(' ') + ' Ihr könnt weiterarbeiten und eine neue Fassung hochladen.'
    : '';
  return { code, hinweis };
}

/* ------------------------------------------------------------------ */
/* .gfar bauen (ZIP ohne Kompression, ohne zusätzliche Pakete)          */
/* ------------------------------------------------------------------ */

const CRC_TAB = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TAB[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function zip(dateien) {   // [{ name, daten: Buffer }]  (Ordner enden auf "/")
  const teile = [], zentral = [];
  let pos = 0;
  const jetzt = new Date();
  const zeit = (jetzt.getHours() << 11) | (jetzt.getMinutes() << 5) | (jetzt.getSeconds() >> 1);
  const datum = ((jetzt.getFullYear() - 1980) << 9) | ((jetzt.getMonth() + 1) << 5) | jetzt.getDate();
  for (const d of dateien) {
    const name = Buffer.from(d.name, 'utf8');
    const daten = d.daten || Buffer.alloc(0);
    const crc = crc32(daten);
    const lok = Buffer.alloc(30);
    lok.writeUInt32LE(0x04034b50, 0); lok.writeUInt16LE(20, 4); lok.writeUInt16LE(0x0800, 6); lok.writeUInt16LE(0, 8);
    lok.writeUInt16LE(zeit, 10); lok.writeUInt16LE(datum, 12); lok.writeUInt32LE(crc, 14);
    lok.writeUInt32LE(daten.length, 18); lok.writeUInt32LE(daten.length, 22); lok.writeUInt16LE(name.length, 26); lok.writeUInt16LE(0, 28);
    teile.push(lok, name, daten);
    const z = Buffer.alloc(46);
    z.writeUInt32LE(0x02014b50, 0); z.writeUInt16LE(20, 4); z.writeUInt16LE(20, 6); z.writeUInt16LE(0x0800, 8); z.writeUInt16LE(0, 10);
    z.writeUInt16LE(zeit, 12); z.writeUInt16LE(datum, 14); z.writeUInt32LE(crc, 16); z.writeUInt32LE(daten.length, 20);
    z.writeUInt32LE(daten.length, 24); z.writeUInt16LE(name.length, 28); z.writeUInt16LE(0, 30); z.writeUInt16LE(0, 32);
    z.writeUInt16LE(0, 34); z.writeUInt16LE(0, 36); z.writeUInt32LE(d.name.endsWith('/') ? 0x10 : 0, 38); z.writeUInt32LE(pos, 42);
    zentral.push(z, name);
    pos += 30 + name.length + daten.length;
  }
  const zgr = zentral.reduce((s, b) => s + b.length, 0);
  const ende = Buffer.alloc(22);
  ende.writeUInt32LE(0x06054b50, 0); ende.writeUInt16LE(dateien.length, 8); ende.writeUInt16LE(dateien.length, 10);
  ende.writeUInt32LE(zgr, 12); ende.writeUInt32LE(pos, 16);
  return Buffer.concat([...teile, ...zentral, ende]);
}

function projectGreenfoot(klassen) {
  const alle = ['Hund', 'Hundeplatz', ...klassen];
  const z = ['#Greenfoot project file', 'class.Hund.image=Deutsche\\ Dogge_steht_0.png', 'class.Hundeplatz.image=platz.png'];
  klassen.forEach(k => z.push(`class.${k}.image=${KLASSE[k].bild}`));
  z.push('dependency1.from=Hundeplatz', 'dependency1.to=Hund', 'dependency1.type=UsesDependency',
    'height=785', 'package.numDependencies=1', `package.numTargets=${alle.length}`, 'project.charset=UTF-8',
    'readme.height=60', 'readme.name=@README', 'readme.width=49', 'readme.x=10', 'readme.y=10', 'simulation.speed=50');
  alle.forEach((k, i) => z.push(`target${i + 1}.height=70`, `target${i + 1}.name=${k}`, `target${i + 1}.showInterface=false`,
    `target${i + 1}.type=ClassTarget`, `target${i + 1}.width=120`, `target${i + 1}.x=0`, `target${i + 1}.y=0`));
  z.push('version=3.1.0', 'width=1058', 'world.lastInstantiated=Hundeplatz', 'xPosition=405', 'yPosition=331');
  return z.join('\n') + '\n';
}

function ordnerName(gname) {
  const n = String(gname || '').normalize('NFKD').replace(/[äÄ]/g, 'ae').replace(/[öÖ]/g, 'oe').replace(/[üÜ]/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 30);
  return 'Hundeschule' + (n ? '_' + n : '');
}

function gfarBauen(gid) {
  const g = Z.gruppen[gid];
  const ordner = ordnerName(g && g.name);
  const paare = paareDerGruppe(gid).filter(p => p.code && p.klasse);
  const klassen = [];
  const dateien = [{ name: ordner + '/' }, { name: ordner + '/images/' }, { name: ordner + '/sounds/' }];
  for (const [name, inhalt] of Object.entries(BASIS)) {
    if (name === 'project.greenfoot') continue;
    dateien.push({ name: `${ordner}/${name}`, daten: Buffer.from(inhalt.b, 'base64') });
  }
  for (const p of paare) {
    if (klassen.includes(p.klasse)) continue;
    klassen.push(p.klasse);
    dateien.push({ name: `${ordner}/${p.klasse}.java`, daten: Buffer.from(p.code, 'utf8') });
  }
  dateien.push({ name: `${ordner}/project.greenfoot`, daten: Buffer.from(projectGreenfoot(klassen), 'utf8') });
  return { ordner, daten: zip(dateien) };
}

/* ------------------------------------------------------------------ */
/* HTTP                                                                */
/* ------------------------------------------------------------------ */

const INDEX = path.join(__dirname, 'index.html');
app.disable('x-powered-by');
app.get(['/', '/lehrkraft'], (req, res) => { res.set('Cache-Control', 'no-store'); res.sendFile(INDEX); });
app.get('/health', (req, res) => res.type('text/plain').send('ok'));
app.get('/config.json', (req, res) => res.json({ passwortNoetig: PASSWORT !== '' }));
app.get('/bild/:name', (req, res) => {
  const k = KLASSEN.find(x => x.bild === req.params.name);
  const b = k && BASIS['images/' + k.bild];
  if (!b) return res.status(404).end();
  res.set('Cache-Control', 'public, max-age=86400').type('png').send(Buffer.from(b.b, 'base64'));
});
app.get('/szenario/:gid', (req, res) => {
  const gid = String(req.params.gid || '');
  const g = Z.gruppen[gid];
  if (!g) return res.status(404).type('text/plain; charset=utf-8').send('Diese Gruppe gibt es nicht (mehr).');
  const lehrkraft = tokens.has(String(req.query.t || ''));
  const p = Z.paare[String(req.query.p || '')];
  if (!lehrkraft) {
    if (!p || p.gruppe !== gid) return res.status(403).type('text/plain; charset=utf-8').send('Nur Paare dieser Gruppe können das Szenario herunterladen.');
    if (!Z.freigabe.download) return res.status(409).type('text/plain; charset=utf-8').send('Der Download ist noch nicht freigegeben.');
    if (!paareDerGruppe(gid).some(x => x.code)) return res.status(409).type('text/plain; charset=utf-8').send('Noch hat kein Paar eurer Gruppe einen Quelltext hochgeladen.');
  }
  const { ordner, daten } = gfarBauen(gid);
  res.set('Content-Disposition', `attachment; filename="${ordner}.gfar"`).type('application/octet-stream').send(daten);
});

/* ------------------------------------------------------------------ */
/* Aktionen                                                            */
/* ------------------------------------------------------------------ */

function paarAnlegen(namen) {
  const id = neueId();
  const rollen = mischen(namen.length === 3 ? ROLLEN.slice() : ROLLEN.slice(0, 2));
  if (namen.length === 3 && rollen[0] === 'Tester') { /* egal: alle drei Rollen kommen vor */ }
  Z.paare[id] = { id, namen, rollen, gruppe: null, klasse: null, code: '', codeZeit: null, hilfen: {}, seit: Date.now() };
  return id;
}

/* Rollentausch: Navigator -> Driver, Driver -> Navigator; im Trio Driver -> Tester -> Navigator -> Driver */
function rollenTauschen() {
  const weiter = { Driver: 'Navigator', Navigator: 'Driver' };
  const weiter3 = { Driver: 'Tester', Tester: 'Navigator', Navigator: 'Driver' };
  for (const p of Object.values(Z.paare)) {
    const map = p.rollen.length === 3 ? weiter3 : weiter;
    p.rollen = p.rollen.map(r => map[r] || r);
  }
  Z.tausch += 1;
}

function gruppeNameFrei(name, ausser) {
  const n = name.toLowerCase();
  return !Object.values(Z.gruppen).some(g => g.id !== ausser && g.name.toLowerCase() === n);
}

function schuelerAktion(socket, typ, d) {
  const pid = Z.paare[String(d.pid || '')] ? String(d.pid) : socket.data.pid;
  const p = pid ? Z.paare[pid] : null;
  switch (typ) {
    case 'eintragen': {
      const r = namenPruefen(d && d.namen);
      if (r.fehler) return { fehler: r.fehler };
      const gleich = Object.values(Z.paare).find(x => x.namen.map(n => n.toLowerCase()).sort().join('|') === r.namen.map(n => n.toLowerCase()).sort().join('|'));
      if (gleich && !(d && d.trotzdem)) return { doppelt: gleich.id };
      const id = paarAnlegen(r.namen);
      socket.data.pid = id;
      return { pid: id };
    }
    case 'waehlen': {
      const id = String(d && d.pid || '');
      if (!Z.paare[id]) return { fehler: 'Dieses Paar gibt es nicht mehr.' };
      socket.data.pid = id;
      return { pid: id };
    }
    case 'gruppeGruenden': {
      if (!p) return { fehler: 'Tragt euch zuerst als Paar ein.' };
      if (!Z.freigabe.gruppen) return { fehler: 'Die Gruppenwahl ist gerade geschlossen.' };
      if (p.code) return { fehler: 'Ihr habt schon abgegeben und könnt die Gruppe nicht mehr wechseln.' };
      const name = text(d && d.name, 30);
      if (!name) return { fehler: 'Gebt eurer Gruppe einen Namen.' };
      if (!gruppeNameFrei(name)) return { fehler: 'Diesen Gruppennamen gibt es schon.' };
      const gid = neueId();
      Z.gruppen[gid] = { id: gid, name, seit: Date.now() };
      p.gruppe = gid; p.klasse = null;
      return {};
    }
    case 'gruppeBeitreten': {
      if (!p) return { fehler: 'Tragt euch zuerst als Paar ein.' };
      if (!Z.freigabe.gruppen) return { fehler: 'Die Gruppenwahl ist gerade geschlossen.' };
      if (p.code) return { fehler: 'Ihr habt schon abgegeben und könnt die Gruppe nicht mehr wechseln.' };
      const gid = String(d && d.gid || '');
      if (!Z.gruppen[gid]) return { fehler: 'Diese Gruppe gibt es nicht mehr.' };
      if (paareDerGruppe(gid).filter(x => x.id !== p.id).length >= MAX_PAARE_PRO_GRUPPE) return { fehler: 'Diese Gruppe hat schon drei Paare.' };
      p.gruppe = gid; p.klasse = null;
      return {};
    }
    case 'gruppeVerlassen': {
      if (!p || !p.gruppe) return {};
      if (!Z.freigabe.gruppen) return { fehler: 'Die Gruppenwahl ist gerade geschlossen.' };
      if (p.code) return { fehler: 'Ihr habt schon abgegeben und könnt die Gruppe nicht mehr wechseln.' };
      const alt = p.gruppe;
      p.gruppe = null; p.klasse = null;
      if (!paareDerGruppe(alt).length) delete Z.gruppen[alt];
      return {};
    }
    case 'hindernisWaehlen': {
      if (!p || !p.gruppe) return { fehler: 'Ihr seid in keiner Gruppe. Meldet euch bei eurer Lehrkraft.' };
      if (!Z.freigabe.wahl) return { fehler: 'Die Wahl ist gerade nicht freigegeben.' };
      const k = String(d && d.klasse || '');
      if (!KLASSE[k]) return { fehler: 'Dieses Hindernis gibt es nicht.' };
      if (p.code && p.klasse !== k) return { fehler: 'Ihr habt schon hochgeladen. Fragt eure Lehrkraft, wenn ihr wechseln wollt.' };
      if (paareDerGruppe(p.gruppe).some(x => x.id !== p.id && x.klasse === k)) return { fehler: 'Dieses Hindernis hat schon ein anderes Paar eurer Gruppe.' };
      if (p.klasse !== k) p.hilfen = {};
      p.klasse = k;
      return {};
    }
    case 'hilfe': {
      if (!p || !p.klasse) return { fehler: 'Wählt zuerst euer Hindernis.' };
      const thema = String(d && d.thema || '');
      const stufe = Number(d && d.stufe);
      if (!HILFE_THEMEN.includes(thema) || ![1, 2].includes(stufe)) return { fehler: 'Diese Hilfe gibt es nicht.' };
      const bisher = (p.hilfen || {})[thema] || 0;
      if (stufe === 2 && bisher < 1) return { fehler: 'Schaut euch zuerst Hilfe 1 an.' };
      p.hilfen = Object.assign({}, p.hilfen, { [thema]: Math.max(bisher, stufe) });
      return {};
    }
    case 'abgeben': {
      if (!p) return { fehler: 'Tragt euch zuerst als Paar ein.' };
      // Hochladen bleibt auch nach dem Ende der Arbeitsphase möglich
      if (!Z.freigabe.abgabe && !Z.freigabe.download) return { fehler: 'Das Hochladen ist noch nicht freigegeben.' };
      if (!p.klasse) return { fehler: 'Wählt zuerst euer Hindernis.' };
      const r = codePruefen(d && d.quelltext, p.klasse);
      if (r.fehler) return { fehler: r.fehler };
      p.code = r.code; p.codeZeit = Date.now();
      return { hinweis: r.hinweis || '' };
    }
    default:
      return { fehler: 'Unbekannte Aktion.' };
  }
}

function ausSicherung(s) {
  if (!s || typeof s !== 'object') return null;
  const z = leererZustand();
  const f = s.freigabe || {};
  z.freigabe = { gruppen: f.gruppen !== false, wahl: !!(f.wahl || f.geraete), abgabe: !!f.abgabe, download: !!f.download };
  z.abgabeBis = text(s.abgabeBis, 10);
  z.tausch = Number.isInteger(s.tausch) && s.tausch >= 0 ? s.tausch : 0;
  for (const g of Array.isArray(s.gruppen) ? s.gruppen : []) {
    if (!g || !ID_RE.test(g.id)) continue;
    const name = text(g.name, 30);
    if (!name) continue;
    z.gruppen[g.id] = { id: g.id, name, seit: Number(g.seit) || Date.now() };
  }
  for (const p of Array.isArray(s.paare) ? s.paare : []) {
    if (!p || !ID_RE.test(p.id)) continue;
    const r = namenPruefen(p.namen);
    if (r.fehler) continue;
    const rollen = Array.isArray(p.rollen) && p.rollen.length === r.namen.length && p.rollen.every(x => ROLLEN.includes(x))
      ? p.rollen : mischen(ROLLEN.slice(0, r.namen.length));
    const gruppe = p.gruppe && z.gruppen[p.gruppe] ? p.gruppe : null;
    const klasse = gruppe && KLASSE[p.klasse] ? p.klasse : null;
    const code = klasse && typeof p.code === 'string' ? p.code.slice(0, MAX_CODE + 40) : '';
    const hilfen = {};
    if (klasse && p.hilfen && typeof p.hilfen === 'object') {
      for (const t of HILFE_THEMEN) if ([1, 2].includes(p.hilfen[t])) hilfen[t] = p.hilfen[t];
    }
    z.paare[p.id] = { id: p.id, namen: r.namen, rollen, gruppe, klasse, code, codeZeit: code ? Number(p.codeZeit) || Date.now() : null, hilfen, seit: Number(p.seit) || Date.now() };
  }
  return z;
}

function lehrerAktion(d) {
  switch (d.typ) {
    case 'freigabe': {
      const k = String(d.was || '');
      if (!(k in Z.freigabe)) return 'Unbekannte Freigabe.';
      Z.freigabe[k] = !!d.an;
      return null;
    }
    case 'abgabeBis':
      Z.abgabeBis = text(d.zeit, 10);
      return null;
    case 'arbeitsphaseBeenden':
      Z.freigabe.wahl = false; Z.freigabe.abgabe = true; Z.freigabe.download = true;
      return null;
    case 'rollenTauschen':
      rollenTauschen();
      return null;
    case 'paarLoeschen': {
      const p = Z.paare[d.pid];
      if (!p) return null;
      const g = p.gruppe;
      delete Z.paare[d.pid];
      if (g && !paareDerGruppe(g).length) delete Z.gruppen[g];
      return null;
    }
    case 'paarGruppe': {
      const p = Z.paare[d.pid];
      if (!p) return 'Paar nicht gefunden.';
      const gid = d.gid ? String(d.gid) : null;
      if (gid && !Z.gruppen[gid]) return 'Gruppe nicht gefunden.';
      if (gid && paareDerGruppe(gid).filter(x => x.id !== p.id).length >= MAX_PAARE_PRO_GRUPPE) return 'Diese Gruppe hat schon drei Paare.';
      const alt = p.gruppe;
      p.gruppe = gid;
      if (gid !== alt) { p.klasse = null; p.code = ''; p.codeZeit = null; p.hilfen = {}; }
      if (alt && alt !== gid && !paareDerGruppe(alt).length) delete Z.gruppen[alt];
      return null;
    }
    case 'paarKlasse': {
      const p = Z.paare[d.pid];
      if (!p) return 'Paar nicht gefunden.';
      const k = d.klasse ? String(d.klasse) : null;
      if (k && !KLASSE[k]) return 'Unbekanntes Hindernis.';
      if (k && p.gruppe && paareDerGruppe(p.gruppe).some(x => x.id !== p.id && x.klasse === k)) return 'Dieses Hindernis hat schon ein anderes Paar der Gruppe.';
      if (k !== p.klasse) { p.code = ''; p.codeZeit = null; p.hilfen = {}; }
      p.klasse = k;
      return null;
    }
    case 'paarRollen': {
      const p = Z.paare[d.pid];
      if (!p) return 'Paar nicht gefunden.';
      p.rollen = mischen(p.rollen.slice());
      return null;
    }
    case 'codeLoeschen': {
      const p = Z.paare[d.pid];
      if (p) { p.code = ''; p.codeZeit = null; }
      return null;
    }
    case 'gruppeNeu': {
      const name = text(d.name, 30);
      if (!name) return 'Name fehlt.';
      if (!gruppeNameFrei(name)) return 'Diesen Gruppennamen gibt es schon.';
      const gid = neueId();
      Z.gruppen[gid] = { id: gid, name, seit: Date.now() };
      return null;
    }
    case 'gruppeUmbenennen': {
      const g = Z.gruppen[d.gid];
      const name = text(d.name, 30);
      if (!g || !name) return null;
      if (!gruppeNameFrei(name, g.id)) return 'Diesen Gruppennamen gibt es schon.';
      g.name = name;
      return null;
    }
    case 'gruppeLoeschen': {
      if (!Z.gruppen[d.gid]) return null;
      for (const p of paareDerGruppe(d.gid)) { p.gruppe = null; p.klasse = null; p.code = ''; p.codeZeit = null; p.hilfen = {}; }
      delete Z.gruppen[d.gid];
      return null;
    }
    case 'allesLoeschen':
      Z = leererZustand();
      return null;
    case 'wiederherstellen': {
      const neu = ausSicherung(d.sicherung);
      if (!neu) return 'Die Sicherung ist unvollständig.';
      if (!istLeer() && !d.ersetzen) return 'Auf dem Server ist schon ein Stand vorhanden.';
      Z = neu;
      return null;
    }
    default:
      return 'Unbekannte Aktion.';
  }
}

/* ------------------------------------------------------------------ */
/* Socket-Verbindungen                                                 */
/* ------------------------------------------------------------------ */

io.on('connection', socket => {
  const ok = fn => (typeof fn === 'function' ? fn : () => {});

  socket.on('s:hallo', (d, ack) => {
    ack = ok(ack);
    socket.join('s');
    const pid = String(d && d.pid || '');
    socket.data.pid = Z.paare[pid] ? pid : null;
    ack({ ok: true, pid: socket.data.pid, zustand: oeffentlich() });
  });

  socket.on('s:aktion', (d, ack) => {
    ack = ok(ack);
    let r;
    try { r = schuelerAktion(socket, String(d && d.typ || ''), d || {}); } catch (e) { console.error(e); r = { fehler: 'Interner Fehler.' }; }
    ack(Object.assign({ ok: !r.fehler && !r.doppelt }, r));
    if (r.fehler || r.doppelt) return;
    verteilen();
  });

  socket.on('lk:anmelden', (d, ack) => {
    ack = ok(ack);
    if (PASSWORT && (!d || d.passwort !== PASSWORT)) return ack({ ok: false, fehler: 'Das Passwort ist falsch.' });
    const token = crypto.randomBytes(16).toString('hex');
    tokens.add(token);
    socket.join('lk');
    socket.data.lk = token;
    ack({ ok: true, token, leer: istLeer(), zustand: voll() });
  });

  socket.on('lk:aktion', (d, ack) => {
    ack = ok(ack);
    if (!d || !socket.data.lk || d.token !== socket.data.lk) return ack({ ok: false, fehler: 'Bitte neu anmelden.' });
    let fehler;
    try { fehler = lehrerAktion(d); } catch (e) { console.error(e); fehler = 'Interner Fehler.'; }
    ack(fehler ? { ok: false, fehler } : { ok: true });
    verteilen();
  });
});

setInterval(() => {
  if (!istLeer() && Z.updatedAt < Date.now() - LEBENSDAUER_MS) { Z = leererZustand(); verteilen(); }
}, 60 * 60 * 1000).unref();

server.listen(PORT, () => {
  console.log(`Hundeschule · Pair Programming läuft auf Port ${PORT}`);
  if (!PASSWORT) console.log('Hinweis: LEHRER_PASSWORT ist nicht gesetzt – die Lehrerseite ist ohne Passwort erreichbar.');
});

